<script setup lang="ts">
import {computed,ref} from 'vue';
import {useCatalog} from '../../utils/catalog';
import {categoryNames,categoryDescriptions} from '../../utils/goods';
import ProductCard from './ProductCard.vue';
const props=defineProps<{title?:string;subtitle?:string;category:string}>();
const {products,loading,error,refresh}=useCatalog();const sort=ref('recommended');
const title=computed(()=>categoryNames[props.category]||props.title||'전체 굿즈');
const subtitle=computed(()=>categoryDescriptions[props.category]||props.subtitle||'부캉이와 함께하는 작은 행복.');
const listed=computed(()=>products.value.filter(product=>['best','all','acc'].includes(props.category)||product.category===categoryNames[props.category]).sort((a,b)=>sort.value==='price-low'?a.finalPrice-b.finalPrice:sort.value==='price-high'?b.finalPrice-a.finalPrice:sort.value==='newest'?Date.parse(b.createdAt)-Date.parse(a.createdAt):(b.metrics?.salesCount||0)-(a.metrics?.salesCount||0)));
</script>
<template>
 <div class="goods-collection"><header class="collection-intro"><p>BUKANGI GOODS COLLECTION</p><h1>{{title}}</h1><span>{{subtitle}}</span></header><nav class="collection-nav" aria-label="굿즈 카테고리"><RouterLink to="/category/best">전체 굿즈</RouterLink><RouterLink to="/category/plush">인형·키링</RouterLink><RouterLink to="/category/living">리빙</RouterLink><RouterLink to="/category/stationery">문구·데스크</RouterLink><RouterLink to="/category/apparel">의류</RouterLink></nav><div class="collection-toolbar"><span>총 <strong>{{listed.length}}</strong>개의 굿즈</span><label>정렬 <select v-model="sort"><option value="recommended">추천순</option><option value="newest">신상품순</option><option value="price-low">낮은 가격순</option><option value="price-high">높은 가격순</option></select></label></div><div v-if="loading" class="collection-state" role="status">귀여운 친구들을 불러오고 있어요.</div><div v-else-if="error" class="collection-state" role="alert">{{error}} <button @click="refresh">다시 시도</button></div><div v-else-if="!listed.length" class="collection-state">아직 등록된 굿즈가 없어요. 조금만 기다려주세요.</div><div v-else class="collection-grid"><ProductCard v-for="product in listed" :key="product._id" :product="product" /></div></div>
</template>
